(7390200, 1161582, 62249, '<td valign="top">Focus seems to be in the wrong place (on the foremost joist) instead of on either the hammer, the end of the board being held, or the model''s face.</td>', 'Focus seems to be in the wrong place (on the foremost joist) instead of on either the hammer, the end of the board being held, or the model''s face.', '2015-07-21 00:11:57.000000', NULL, 1),
(7390202, 1160815, 62249, '<td valign="top">This is a strange composition. Can''t tell what I''m supposed to look at (the foot, the chamber pot, the zigzag design, the graffiti) or what story it''s trying to tell. Still, it draws a viewer in to try to figure it out.</td>', 'This is a strange composition. Can''t tell what I''m supposed to look at (the foot, the chamber pot, the zigzag design, the graffiti) or what story it''s trying to tell. Still, it draws a viewer in to try to figure it out.', '2015-07-21 00:13:42.000000', NULL, 1),
(7390203, 1161513, 62249, '<td valign="top">I like it. The different angles &amp; tones are interest, especially since they aren''t symmetrical. A bit more contrast might''ve been nice, but Minimal editing removes that option.</td>', 'I like it. The different angles & tones are interest, especially since they aren''t symmetrical. A bit more contrast might''ve been nice, but Minimal editing removes that option.', '2015-07-21 00:14:56.000000', NULL, 1),
(7390204, 1161580, 62249, '<td valign="top">Clever and looks good even with minimal editing. Good background, good tonal range.</td>', 'Clever and looks good even with minimal editing. Good background, good tonal range.', '2015-07-21 00:15:30.000000', NULL, 1),
(7390283, 1161372, 114285, '<td valign="top">This photo is accentuated even more by the slant, almost gives it a 3D effect when I look downstairs, great light of course. Top three I feel.</td>', 'This photo is accentuated even more by the slant, almost gives it a 3D effect when I look downstairs, great light of course. Top three I feel.', '2015-07-21 09:21:46.000000', NULL, 1),
(7390311, 1161523, 180710, '<td valign="top">Great concept and excecution!</td>', 'Great concept and excecution!', '2015-07-21 10:13:25.000000', NULL, 1),
